import {
    add,
    addHours,
    addMinutes,
    differenceInMinutes,
    getUnixTime,
    isAfter,
    isBefore,
    isSameDay,
    roundToNearestMinutes,
} from 'date-fns';
import { capitalizeFirstLetter, removeEmptyFields } from '../general';
import { WeekOfMonth } from '../recurrence';
import { endOfDayInTimezone, startOfDayInTimezone } from '../timezone-helpers';
import { LinkedBooking } from '../types';
import { AssetRequest } from './asset-request.class';
import { User } from './user.class';

export type BookingType =
    | 'desk'
    | 'group'
    | 'parking'
    | 'locker'
    | 'room'
    | 'visitor'
    | 'asset-request'
    | 'staff'
    | 'group-event'
    | 'catering-order'
    | ' ';
const IGNORE_EXT_KEYS = ['user', 'booked_by', 'resources', 'assets', 'members'];

export interface BookingComplete extends Booking {
    members?: User[];
    guests?: User[];
}

export interface BookingClash {
    asset_id: string;
    booking_start: number;
    booking_end: number;
}

export type BookingHistoryState =
    | 'reserved'
    | 'checked_in'
    | 'checked_out'
    | 'no_show'
    | 'rejected'
    | 'cancelled'
    | 'ended'
    | 'unknown';

export interface BookingHistory {
    state: BookingHistoryState;
    time: number;
    source?: string;
}

export enum RecurrenceDays {
    SUNDAY = 1 << 0,
    MONDAY = 1 << 1,
    TUESDAY = 1 << 2,
    WEDNESDAY = 1 << 3,
    THURSDAY = 1 << 4,
    FRIDAY = 1 << 5,
    SATURDAY = 1 << 6,
}

export interface LinkedCalendarEvent {
    id?: string;
    date: number;
    duration: number;
    date_end: number;
    system_id: string;
    resource_calendar: string;
    event_id: string;
    host_email: string;
    ical_uid?: string;
}

const DAY_MINUTES = 24 * 60;

/** Start, length and end of a booking in milliseconds and minutes */
interface BookingWindow {
    date: number;
    duration: number;
    date_end: number;
}

/** Display name of the booked asset. Visitor bookings prefer the visitor name. */
function resolveAssetName(
    data: Partial<BookingComplete>,
    booking_type: string,
): string {
    const ext = data.extension_data;
    const name = data.asset_name || ext?.asset_name || ext?.name;
    if (booking_type === 'visitor') {
        return ext?.visitor_name || name || data.asset_id || '';
    }
    return name || data.description || data.asset_id || '';
}

/**
 * Start and end of the booking in unix seconds.
 * Without a start, the booking starts on the next 5 minute mark after now + 5 minutes.
 */
function resolveUnixWindow(data: Partial<BookingComplete>): {
    start: number;
    end: number;
} {
    const duration = data.duration || 60;
    // `date`/`duration` are the source of truth for the booking window.
    // Both ends must derive from the same source so we never pair a fresh
    // start (from `date`) with a stale `booking_end` (which can invert the
    // window and send booking_end before booking_start to the API).
    if (data.date) {
        const start = Math.floor(data.date / 1000);
        return { start, end: start + duration * 60 };
    }
    const start =
        data.booking_start ||
        getUnixTime(
            roundToNearestMinutes(addMinutes(Date.now(), 5), {
                nearestTo: 5,
            }),
        );
    return {
        start,
        end:
            data.booking_end || getUnixTime(addMinutes(start * 1000, duration)),
    };
}

/** Booking window in milliseconds from `date`/`duration`, else from the unix window */
function toBookingWindow(
    data: Partial<BookingComplete>,
    start: number,
    end: number,
): BookingWindow {
    const date = data.date || start * 1000 || Date.now();
    const span = Math.abs(differenceInMinutes(start * 1000, end * 1000));
    // An explicit end is the source of truth over a stored duration.
    const duration = data.booking_end
        ? span || 60
        : data.duration || span || 60;
    return {
        date,
        duration,
        date_end: end * 1000 || date + duration * 60 * 1000,
    };
}

/** Whether the raw data flags the booking as a custom all day booking */
function isCustomAllDay(data: Partial<BookingComplete>): boolean {
    return !!(
        data.extension_data?.custom_all_day ||
        (data as Record<string, unknown>).custom_all_day
    );
}

/**
 * Snap the window of an all day booking to whole days in `timezone`.
 * Only applies when the data has no explicit length, or the length is whole days.
 */
function snapToWholeDays(
    data: Partial<BookingComplete>,
    window: BookingWindow,
    timezone: string,
): BookingWindow {
    const has_length = !!(data.duration || data.date_end || data.booking_end);
    if (has_length && window.duration % DAY_MINUTES !== 0) return window;
    const date = startOfDayInTimezone(window.date, timezone);
    return {
        date,
        duration: has_length
            ? Math.max(1, window.duration - 1)
            : DAY_MINUTES - 1,
        date_end: endOfDayInTimezone(date, timezone),
    };
}

/** Booking status from local flags first, then the status sent by the server */
function resolveStatus(
    booking: Pick<Booking, 'deleted' | 'rejected' | 'approved' | 'has_ended'>,
    status: Booking['status'] | undefined,
): Booking['status'] {
    if (booking.deleted || status === 'cancelled') return 'cancelled';
    if (booking.rejected || status === 'declined') return 'declined';
    if (booking.has_ended) return 'ended';
    if (booking.approved || status === 'approved') return 'approved';
    return 'tentative';
}

/** Copy truthy fields that the booking does not define into its extension data */
function copyUnknownFields(
    booking: Booking,
    data: Partial<BookingComplete>,
): void {
    for (const key in data) {
        if (!(key in booking) && !IGNORE_EXT_KEYS.includes(key) && data[key]) {
            booking.extension_data[key] = data[key];
        }
    }
}

/** General purpose booking class */
export class Booking {
    /** Unique Identifier of the object */
    public readonly id: string;
    /** Identifier of the parent booking */
    public readonly parent_id: string;
    /** Unix epoch for the start time of the booking in seconds */
    public readonly booking_start: number;
    /** Unix epoch for the start time of the booking in seconds */
    public readonly booking_end: number;
    /** ID of the user who owns the booking */
    public readonly booked_by_id: string;
    /** Email of the user who owns the booking */
    public readonly booked_by_email: string;
    /** Display name of the user who owns the booking */
    public readonly booked_by_name: string;
    /** ID of the user who owns the booking */
    public readonly user_id: string;
    /** Email of the user who owns the booking */
    public readonly user_email: string;
    /** Display name of the user who owns the booking */
    public readonly user_name: string;
    /** ID of an associated calendar event */
    public readonly event_id?: string;
    /** Identifier of the physical asset assocated with the booking */
    public readonly asset_id: string;
    /** List of identifier of the physical assets assocated with the booking */
    public readonly asset_ids: string[];
    /** Name of the physical asset assocated with the booking */
    public readonly asset_name: string;
    /** Zones associated with the asset ID */
    public readonly zones: string[];
    /** Type of booking */
    public readonly booking_type: BookingType;
    /** Start time of booking in ms */
    public readonly date: number;
    /** End time of booking in ms */
    public readonly date_end: number;
    /** Duration of the event in minutes */
    public readonly duration: number;
    /** Whether it is an all day booking */
    public readonly all_day: boolean;
    /** Timezone of the booking */
    public readonly timezone: string;
    /** Title of the booking */
    public readonly title: string;
    /** Description */
    public readonly description: string;
    /** Whether user checked in */
    public readonly checked_in: boolean;
    /** Whether booking is rejected */
    public readonly rejected: boolean;
    /** Whether booking is approved */
    public readonly approved: boolean;
    /** Id of the approver */
    public readonly approver_id: string;
    /** Email of the approver */
    public readonly approver_email: string;
    /** Name of the approver */
    public readonly approver_name: string;
    /** Extra non-standard metadata associated with the booking */
    public readonly extension_data: Record<string, any>;
    /** Default type */
    public readonly type: string;
    /** List of URLs for associated booking images */
    public readonly images: string[];
    /** List of user defined tags associated with the booking */
    public readonly tags: string[];

    public readonly permission: 'PRIVATE' | 'OPEN' | 'PUBLIC';
    /** Default type */
    public readonly access: boolean;
    /** Whether asset has been inducted */
    public readonly induction?: 'tentative' | 'accepted' | 'declined';
    /** Status of the booking */
    public readonly status:
        | 'declined'
        | 'cancelled'
        | 'approved'
        | 'tentative'
        | 'ended';
    /** New deleted field */
    public readonly deleted: boolean;
    /** List of attendees for the booking */
    public readonly attendees: User[];
    /** Time that the booking was checked out */
    public readonly checked_out_at?: number;
    /** Time that the booking was checked in */
    public readonly checked_in_at?: number;
    /** Details of the linked calendar event */
    public readonly linked_event?: LinkedCalendarEvent;
    /** Details of the linked bookings */
    public readonly linked_bookings: LinkedBooking[];
    /** Details of the parent booking */
    public readonly linked_parent_booking?: LinkedBooking;

    public readonly process_state: string;
    /** Unix epoch for the start time of the reccurence instance in seconds. Only set when instance of a recurring series */
    public readonly instance?: number;
    /** Type of recurrence instance */
    public readonly recurrence_type: 'none' | 'daily' | 'weekly' | 'monthly';
    /** Bit flags for the recurrence days of the week */
    public readonly recurrence_days?: number;
    /** Week of the month to recur on */
    public readonly recurrence_nth_of_month?: WeekOfMonth;
    /** How often to recur */
    public readonly recurrence_interval?: number;
    /** Unix epoch for the end time of the recurrence in seconds */
    public readonly recurrence_end?: number;
    /** Unix epoch for the booking creation time in seconds */
    public readonly created_at: number;
    /** Chronological state changes recorded for the booking */
    public readonly history: BookingHistory[];

    public get group() {
        return this.extension_data.group || '';
    }

    public get is_all_day() {
        return this.all_day || this.duration >= 18 * 60;
    }

    public get has_ended() {
        return this.checked_out_at > 0 || isAfter(Date.now(), this.date_end);
    }

    _valid_asset_cache = [];
    _valid_cache_expiry = 0;

    public get valid_assets() {
        if (
            this._valid_cache_expiry > Date.now() &&
            this._valid_asset_cache.length
        ) {
            return this._valid_asset_cache;
        }
        const list = this.linked_bookings;
        this._valid_asset_cache = (this.extension_data.assets || [])
            .map((request) => new AssetRequest({ ...request, event: this }))
            .filter((request) => request.deliver_at < this.date_end)
            .map((request) => {
                const booking = list.find(
                    (_: any) => _.extension_data.request_id === request.id,
                );
                if (booking) {
                    (request as any).state = booking.approved
                        ? 'approved'
                        : booking.rejected
                          ? 'rejected'
                          : 'pending';
                }
                return request;
            });
        this._valid_cache_expiry = addMinutes(Date.now(), 5).valueOf();
        return this._valid_asset_cache;
    }

    constructor(data: Partial<BookingComplete> = {}) {
        this.id = data.id || '';
        this.parent_id = data.parent_id || '';
        this.asset_id = data.asset_id || '';
        this.asset_ids = data.asset_ids || [data.asset_id].filter((_) => _);
        this.asset_name = resolveAssetName(
            data,
            data.booking_type || data.type || ' ',
        );
        this.zones = data.zones || [];
        const { start, end } = resolveUnixWindow(data);
        this.booking_start = start;
        this.booking_end = end;
        this.booking_type = data.booking_type || ' ';
        this.type = data.type || data.booking_type || 'booking';
        const timezone =
            data.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone;
        const base_window = toBookingWindow(data, start, end);
        const all_day =
            !!data.all_day ||
            isCustomAllDay(data) ||
            base_window.duration >= DAY_MINUTES;
        const window = all_day
            ? snapToWholeDays(data, base_window, timezone)
            : base_window;
        this.date = window.date;
        this.duration = window.duration;
        this.date_end = window.date_end;
        this.timezone = timezone;
        this.user_email = data.user_email || '';
        this.user_id = data.user_id || '';
        this.user_name = data.user_name || '';
        this.title =
            data.title ??
            (this.booking_type
                ? `${capitalizeFirstLetter(this.booking_type)} Booking`.trim()
                : '');
        this.description = data.description || '';
        this.checked_in = !!data.checked_in;
        this.rejected = !!data.rejected;
        this.approved = !!data.approved;
        this.deleted = !!data.deleted;
        this.booked_by_id = data.booked_by_id || '';
        this.booked_by_name = data.booked_by_name || '';
        this.booked_by_email = data.booked_by_email || '';
        this.approver_id = data.approver_id || '';
        this.approver_email = data.approver_email || '';
        this.approver_name = data.approver_name || '';
        this.extension_data = data.extension_data || {};
        this.access = !!data.extension_data?.access;
        this.event_id = data.event_id;
        this.permission = (
            data.permission || 'PRIVATE'
        ).toUpperCase() as Booking['permission'];
        this.attendees = data.attendees || data.guests || data.members || [];
        this.tags = data.tags || data.extension_data?.tags || [];
        this.images = data.images || [];
        this.all_day = all_day;
        this.induction = data.induction || undefined;
        this.created_at = data.created_at || Date.now();
        this.history = data.history || [];
        this.checked_out_at = data.checked_out_at;
        this.checked_in_at = data.checked_in_at;
        this.linked_event = data.linked_event || null;
        this.linked_bookings = data.linked_bookings || [];
        this.linked_parent_booking = data.linked_parent_booking || null;
        this.status = resolveStatus(this, data.status);
        this.process_state = data.process_state || 'pending';

        this.recurrence_type = data.recurrence_type || 'none';
        this.recurrence_days = data.recurrence_days;
        this.recurrence_nth_of_month = data.recurrence_nth_of_month;
        this.recurrence_interval = data.recurrence_interval;
        this.recurrence_end = data.recurrence_end;
        this.instance = data.instance;

        copyUnknownFields(this, data);
        this.extension_data.assets = (this.extension_data.assets || []).map(
            (i) =>
                new AssetRequest({ ...i, event: this, date: this.date } as any),
        );
        this.extension_data.tags = data.tags || [];
        if (this.extension_data.request) {
            this.extension_data.request = new AssetRequest({
                ...this.extension_data.request,
                event: this,
                date: this.date,
            } as any);
        }
    }

    public toJSON(this: Booking): Partial<Booking> {
        const data = { ...this };
        if (!this.id) delete data.id;
        data.extension_data.assets = data.extension_data.assets.map(
            (i) => new AssetRequest({ ...i, event: null }),
        );
        if (data.extension_data.request) {
            data.extension_data.request = new AssetRequest({
                ...data.extension_data.request,
                event: null,
            });
        }
        if (!data.parent_id) delete data.parent_id;
        data.zones = data.zones.filter((_) => _);
        delete data.date;
        delete data.duration;
        delete data.created_at;
        delete data.history;
        delete data.process_state;
        removeEmptyFields(data);
        return data;
    }

    public get location(): string {
        return this.extension_data?.location || this.description;
    }

    /** Whether the booking occurs today */
    public get is_today(): boolean {
        return isSameDay(this.date, new Date());
    }

    /** Whether booking is done */
    public get is_done(): boolean {
        const start = new Date();
        const end = this.all_day
            ? addHours(this.date, 24)
            : addMinutes(this.date, this.duration);
        const checked_out =
            (this.checked_out_at || this.extension_data.checked_out_at || 0) *
            1000;
        const end_time = end.getTime();
        if (checked_out && Date.now() > checked_out) return true;
        return isAfter(start, new Date(end_time));
    }

    /** Status of the booking */
    public get state():
        | 'future'
        | 'upcoming'
        | 'done'
        | 'started'
        | 'in_progress' {
        const now = new Date();
        const date = this.date;
        if (isBefore(now, add(date, { minutes: -15 }))) return 'future';
        if (isBefore(now, date)) return 'upcoming';
        if (isBefore(now, add(date, { minutes: 15 }))) return 'started';
        if (isBefore(now, add(date, { minutes: this.duration })))
            return 'in_progress';
        return 'done';
    }
}
